export function writeIco(images) {
  const sorted = [...images].sort((a, b) => a.width - b.width);
  // PNG payloads are only guaranteed to load at 256 px; everything smaller is
  // a plain 32-bit DIB, which every shell component since XP renders.
  const blobs = sorted.map((im) => (im.width >= 256 ? encodePng(im) : encodeDib(im)));
  const header = Buffer.alloc(6 + 16 * sorted.length);
  header.writeUInt16LE(0, 0); header.writeUInt16LE(1, 2); header.writeUInt16LE(sorted.length, 4);
  let offset = header.length;
  sorted.forEach((im, i) => {
    const e = 6 + i * 16;
    header[e] = im.width >= 256 ? 0 : im.width;
    header[e + 1] = im.height >= 256 ? 0 : im.height;
    header[e + 2] = 0; header[e + 3] = 0;
    header.writeUInt16LE(1, e + 4);
    header.writeUInt16LE(32, e + 6);
    header.writeUInt32LE(blobs[i].length, e + 8);
    header.writeUInt32LE(offset, e + 12);
    offset += blobs[i].length;
  });
  return Buffer.concat([header, ...blobs]);
}


// ---- icns.js
// Apple .icns reader/writer, PNG payloads only (what electron-builder and
// iconutil produce). Older RLE types are skipped on read.

const TYPES = [
  ['icp4', 16], ['icp5', 32], ['icp6', 64], ['ic07', 128], ['ic08', 256], ['ic09', 512], ['ic10', 1024],
  ['ic11', 32], ['ic12', 64], ['ic13', 256], ['ic14', 512],
];

export const ICNS_SIZES = [16, 32, 64, 128, 256, 512, 1024];

export function readIcns(buf) {
  if (buf.toString('latin1', 0, 4) !== 'icns') throw new Error('Not an ICNS');
  const total = buf.readUInt32BE(4);
  const entries = [];
  let pos = 8;
  while (pos + 8 <= Math.min(total, buf.length)) {
    const type = buf.toString('latin1', pos, pos + 4);
    const len = buf.readUInt32BE(pos + 4);
    if (len < 8) break;
    const data = buf.subarray(pos + 8, pos + len);
    if (isPng(data)) entries.push({ type, width: data.readUInt32BE(16), height: data.readUInt32BE(20), data });
    pos += len;
  }
  return entries;
}

export function largestFromIcns(buf) {
  const entries = readIcns(buf).sort((a, b) => b.width - a.width);
  if (!entries.length) return null;
  return decodePng(entries[0].data);
}

// images: array of RGBA images at the sizes in TYPES (missing sizes skipped).
export function writeIcns(images) {
  const bySize = new Map(images.map((im) => [im.width, im]));
  const parts = [];
  for (const [type, size] of TYPES) {
    const im = bySize.get(size);
    if (!im) continue;
    const png = encodePng(im);
    const hdr = Buffer.alloc(8);
    hdr.write(type, 0, 'latin1');
    hdr.writeUInt32BE(8 + png.length, 4);
    parts.push(hdr, png);
  }
  const body = Buffer.concat(parts);
  const head = Buffer.alloc(8);
  head.write('icns', 0, 'latin1');
  head.writeUInt32BE(8 + body.length, 4);
  return Buffer.concat([head, body]);
}


// ---- resize.js
// Area-averaging resize on premultiplied alpha, so soft edges don't pick up
// dark fringes. Good for icon downscales; upscales use the same kernel.
export function resize(img, w, h) {
  if (w === img.width && h === img.height) return { width: w, height: h, data: new Uint8Array(img.data) };
  const src = img.data;
  const sw = img.width, sh = img.height;
  const pre = new Float32Array(sw * sh * 4);
  for (let i = 0; i < src.length; i += 4) {
    const a = src[i + 3] / 255;
    pre[i] = src[i] * a; pre[i + 1] = src[i + 1] * a; pre[i + 2] = src[i + 2] * a; pre[i + 3] = a;
  }
  const tmp = new Float32Array(w * sh * 4);
  scaleAxis(pre, sw, sh, tmp, w, true);
  const outF = new Float32Array(w * h * 4);
  scaleAxis(tmp, w, sh, outF, h, false);
  const out = new Uint8Array(w * h * 4);
  for (let i = 0; i < out.length; i += 4) {
    const a = outF[i + 3];
    if (a <= 0) continue;
    out[i] = clamp(outF[i] / a); out[i + 1] = clamp(outF[i + 1] / a); out[i + 2] = clamp(outF[i + 2] / a);
    out[i + 3] = clamp(a * 255);
  }
  return { width: w, height: h, data: out };
}

function clamp(v) { return v < 0 ? 0 : v > 255 ? 255 : Math.round(v); }

// Resample one axis with a box filter (fractional coverage at the ends).
function scaleAxis(src, sw, sh, dst, dlen, horizontal) {
  const slen = horizontal ? sw : sh;
  const other = horizontal ? sh : sw;
  const dw = horizontal ? dlen : sw;
  const scale = slen / dlen;
  for (let d = 0; d < dlen; d++) {
    const start = d * scale, end = start + scale;
    const s0 = Math.floor(start), s1 = Math.min(slen - 1, Math.ceil(end) - 1);
    for (let o = 0; o < other; o++) {
      let r = 0, g = 0, b = 0, a = 0, wsum = 0;
      for (let s = s0; s <= s1; s++) {
        const wgt = Math.min(end, s + 1) - Math.max(start, s);
        if (wgt <= 0) continue;
        const i = horizontal ? (o * sw + s) * 4 : (s * sw + o) * 4;
        r += src[i] * wgt; g += src[i + 1] * wgt; b += src[i + 2] * wgt; a += src[i + 3] * wgt; wsum += wgt;
      }
      const j = horizontal ? (o * dw + d) * 4 : (d * dw + o) * 4;
      dst[j] = r / wsum; dst[j + 1] = g / wsum; dst[j + 2] = b / wsum; dst[j + 3] = a / wsum;
    }
  }
}


// ---- recolor.js
// Recolours an app icon toward a target colour so a set of icons reads as
// one family. Two treatments, chosen automatically from the icon itself:
//
//   hue   — colourful icons (Claude's orange tile). Every pixel keeps its
//           lightness and relative chroma and has its hue rotated so the
//           dominant colour lands on the target hue. Done in OKLCH, so the
//           drop shadow, texture and near-white marks survive untouched.
//   ramp  — grayscale icons (ChatGPT's knot, Grok Bot's ghost), where a hue
//           rotation is a no-op. Lightness is remapped through a ramp whose
//           stops are placed so the icon's own field lands exactly on the
//           target colour and the mark lands on white. A dark field gets a
//           third stop below it so outlines darker than the field stay
//           darker instead of collapsing into it.
//
// Ramps interpolate in OKLab so midpoints don't go muddy.

const OPAQUE = 128;

export function analyze(img) {
  const { data, width, height } = img;
  let n = 0, sumC = 0;
  let wx = 0, wy = 0, wSum = 0, wL = 0, wC = 0;
  const lums = [];
  let x0 = width, y0 = height, x1 = -1, y1 = -1;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < OPAQUE) continue;
    const p = i >> 2, x = p % width, y = (p / width) | 0;
    if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y;
    const [L, a, b] = linearToOklab(LIN[data[i]], LIN[data[i + 1]], LIN[data[i + 2]]);
    const C = Math.hypot(a, b);
    n++; sumC += C; lums.push(L);
    if (C > 0.04) {
      // chroma-weighted circular mean of hue
      wx += a; wy += b; wSum += C; wL += L * C; wC += C * C;
    }
  }
  if (n === 0) throw new Error('Icon has no opaque pixels');
  const meanChroma = sumC / n;
  // The field is whatever colour the icon's outer edge mostly is: the modal
  // lightness of opaque pixels in a thin band inside the bounding box. A mean
  // or median fails when the mark is bigger than the field or touches the
  // edge (Grok Bot's ghost fills the tile and is cut off at the bottom).
  const band = Math.max(2, Math.round(0.06 * Math.min(x1 - x0 + 1, y1 - y0 + 1)));
  const BINS = 20;
  const hist = new Array(BINS).fill(0);
  const sums = new Array(BINS).fill(0);
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      if (x - x0 >= band && x1 - x >= band && y - y0 >= band && y1 - y >= band) { x = x1 - band; continue; }
      const i = (y * width + x) * 4;
      if (data[i + 3] < OPAQUE) continue;
      const L = linearToOklab(LIN[data[i]], LIN[data[i + 1]], LIN[data[i + 2]])[0];
      const b = Math.min(BINS - 1, Math.floor(L * BINS));
      hist[b]++; sums[b] += L;
    }
  }
  let mode = 0;
  for (let b = 1; b < BINS; b++) if (hist[b] > hist[mode]) mode = b;
  let cnt = 0, sum = 0;
  for (let b = Math.max(0, mode - 1); b <= Math.min(BINS - 1, mode + 1); b++) { cnt += hist[b]; sum += sums[b]; }
  const fieldL = cnt ? sum / cnt : lums.reduce((s, v) => s + v, 0) / n;
  let dominant = null;
  if (wSum > 0) {
    let h = (Math.atan2(wy, wx) * 180) / Math.PI;
    if (h < 0) h += 360;
    dominant = { h, L: wL / wSum, C: wC / wSum };
  }
  let darker = 0;
  for (const L of lums) if (L < fieldL - 0.08) darker++;
  return { meanChroma, fieldL, dominant, darkerFraction: darker / n, opaquePixels: n };
}

export function chooseTreatment(stats) {
  if (stats.meanChroma > 0.05 && stats.dominant) return 'hue';
  return stats.fieldL > 0.5 ? 'ramp-light' : 'ramp-dark';
}

function toOklab(hex) {
  const [L, C, h] = hexToOklch(hex);
  return oklchToOklab(L, C, h);
}

function lerpLab(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function labToBytes(lab) {
  const [Lc, C, h] = oklabToOklch(lab[0], lab[1], lab[2]);
  const rgb = oklchToLinearClamped(Lc, C, h);
  return rgb.map((v) => Math.round(linearToSrgb(v) * 255));
}

/**
 * @param {{width:number,height:number,data:Uint8Array}} img straight-alpha RGBA
 * @param {string} targetHex e.g. "#1b91e3"
 * @param {{treatment?: 'auto'|'hue'|'ramp-light'|'ramp-dark', stats?: object}} [opts]
 */
export function recolor(img, targetHex, opts = {}) {
  const stats = opts.stats || analyze(img);
  const treatment = !opts.treatment || opts.treatment === 'auto' ? chooseTreatment(stats) : opts.treatment;
  const out = new Uint8Array(img.data.length);
  const { data } = img;
  const [tL, tC, tH] = hexToOklch(targetHex);
  const cache = new Map();

  if (treatment === 'hue') {
    const d = stats.dominant;
    const delta = tH - d.h;
    const cScale = Math.min(2, Math.max(0.5, tC / Math.max(d.C, 1e-4)));
    const lShift = tL - d.L;
    for (let i = 0; i < data.length; i += 4) {
      const a = data[i + 3];
      out[i + 3] = a;
      if (a === 0) continue;
      const key = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
      let px = cache.get(key);
      if (!px) {
        const [L, la, lb] = linearToOklab(LIN[data[i]], LIN[data[i + 1]], LIN[data[i + 2]]);
        const [, C, h] = oklabToOklch(L, la, lb);
        // Field pixels (chroma near the dominant) take the full lightness
        // shift; near-neutral marks, shadows and highlights take almost none,
        // so cream stays cream and the shadow stays a shadow.
        const w = Math.min(1, C / Math.max(d.C, 1e-4));
        const rgb = oklchToLinearClamped(L + lShift * w, C * cScale, (h + delta + 360) % 360);
        px = rgb.map((v) => Math.round(linearToSrgb(v) * 255));
        cache.set(key, px);
      }
      out[i] = px[0]; out[i + 1] = px[1]; out[i + 2] = px[2];
    }
    return { img: { width: img.width, height: img.height, data: out }, treatment, stats };
  }

  const target = toOklab(targetHex);
  const white = [1, 0, 0];
  const field = Math.min(0.98, Math.max(0.02, stats.fieldL));
  let stops;
  if (treatment === 'ramp-light') {
    // Dark mark on a light field: black -> white, field -> target.
    stops = [[0, white], [field, target], [1, target]];
  } else {
    // Light mark on a dark field: field -> target, white -> white, and a
    // darker version of the target below the field for outlines.
    const [L, C, h] = hexToOklch(targetHex);
    const darker = oklchToOklab(Math.max(0.05, L - 0.25), C * 0.8, h);
    stops = stats.darkerFraction > 0.01 ? [[0, darker], [field, target], [1, white]] : [[0, target], [field, target], [1, white]];
  }
  for (let i = 0; i < data.length; i += 4) {
    const a = data[i + 3];
    out[i + 3] = a;
    if (a === 0) continue;
    const key = (data[i] << 16) | (data[i + 1] << 8) | data[i + 2];
    let px = cache.get(key);
    if (!px) {
      const [L] = linearToOklab(LIN[data[i]], LIN[data[i + 1]], LIN[data[i + 2]]);
      let lab = stops[stops.length - 1][1];
      if (L <= stops[0][0]) lab = stops[0][1];
      else {
        for (let s = 0; s < stops.length - 1; s++) {
          const [l0, c0] = stops[s], [l1, c1] = stops[s + 1];
          if (L >= l0 && L <= l1) { lab = l1 === l0 ? c1 : lerpLab(c0, c1, (L - l0) / (l1 - l0)); break; }
        }
      }
      px = labToBytes(lab);
      cache.set(key, px);
    }
    out[i] = px[0]; out[i + 1] = px[1]; out[i + 2] = px[2];
  }
  return { img: { width: img.width, height: img.height, data: out }, treatment, stats };
}


// ---- palette.js
// Named profile colours. All sit at the same OKLCH lightness and chroma as
// the original work blue (#1b91e3 ≈ L 0.63, C 0.16, h 245), so a Dock or
// taskbar full of dupes reads as one family and differs only by hue.

const L = 0.63, C = 0.16;

export const NAMED = {
  blue: oklchToHex(L, C, 245),
  teal: oklchToHex(L, C, 195),
  green: oklchToHex(L, C, 150),
  amber: oklchToHex(L, C, 75),
  red: oklchToHex(L, C, 25),
  pink: oklchToHex(L, C, 345),
  purple: oklchToHex(L, C, 300),
  gray: oklchToHex(L, 0.02, 245),
};

// Stephen Wu's original work blue, kept exact rather than regenerated.
NAMED.blue = '#1b91e3';

export const ORDER = ['blue', 'green', 'purple', 'amber', 'red', 'teal', 'pink', 'gray'];

/** Accepts "#1b91e3", "1b91e3" or a palette name. */
export function resolveColor(input) {
  if (!input) return null;
  const key = String(input).trim().toLowerCase();
  if (NAMED[key]) return NAMED[key];
  hexToOklch(key); // throws on bad input
  return key.startsWith('#') ? key : `#${key}`;
}

/** Next unused palette colour for an app that already has `used` colours. */
export function nextColor(used) {
  const taken = new Set(used.map((c) => c.toLowerCase()));
  for (const name of ORDER) if (!taken.has(NAMED[name])) return NAMED[name];
  return NAMED.blue;
}
